import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Generate a list of overdue invoices.
 * @param {Array<{ number: string, customerId: string, dueDate: string, status: string, payments?: Array }>} invoices - All invoices
 * @param {string} asOf - Report date (YYYY-MM-DD)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((invoice) => {
      // Check status is issued or partially_paid
      if (!['issued', 'partially_paid'].includes(invoice.status)) return false;
      // Check dueDate is before asOf
      if (invoice.dueDate >= asOf) return false;
      return true;
    })
    .map((invoice) => {
      // Calculate days overdue
      const dueDate = new Date(invoice.dueDate + 'T00:00:00Z');
      const asOfDate = new Date(asOf + 'T00:00:00Z');
      const daysOverdue = Math.floor((asOfDate - dueDate) / (1000 * 60 * 60 * 24));

      return {
        number: invoice.number,
        customerId: invoice.customerId,
        dueDate: invoice.dueDate,
        daysOverdue,
        due: balanceDue(invoice),
      };
    })
    .sort((a, b) => {
      // Most overdue first = oldest dueDate first
      return a.dueDate.localeCompare(b.dueDate);
    });

  return overdue;
}

/**
 * Generate a VAT summary by rate for invoices.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices - All invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} - One entry per VAT rate, sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  // Process invoices with issued, partially_paid, or paid status
  invoices
    .filter((invoice) => ['issued', 'partially_paid', 'paid'].includes(invoice.status))
    .forEach((invoice) => {
      invoice.lines.forEach((line) => {
        const rate = line.vatRate ?? 0;
        const base = Math.max(0, lineTotal(line) - lineDiscount(line));
        const vat = lineVat(line);

        if (!vatMap.has(rate)) {
          vatMap.set(rate, { base: 0, vat: 0 });
        }

        const current = vatMap.get(rate);
        current.base += base;
        current.vat += vat;
      });
    });

  // Convert to array, add rate, and sort by rate descending
  const summary = Array.from(vatMap.entries())
    .map(([rate, { base, vat }]) => ({
      rate,
      base: roundCents(base),
      vat: roundCents(vat),
    }))
    .sort((a, b) => b.rate - a.rate);

  return summary;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

// Helper to create and issue an invoice
function createAndIssueInvoice(customerId, issueDate, lines, terms = 'NET30') {
  const draftResult = createInvoice({
    customerId,
    issueDate,
    lines,
    terms,
  });
  if (!draftResult.ok) throw new Error(`Failed to create invoice: ${draftResult.error}`);

  const issuedResult = issueInvoice(draftResult.value, []);
  if (!issuedResult.ok) throw new Error(`Failed to issue invoice: ${issuedResult.error}`);

  return issuedResult.value;
}

test('overdueInvoices returns empty array for empty list', () => {
  const r = overdueInvoices([], '2025-03-15');
  assert.equal(Array.isArray(r), true);
  assert.equal(r.length, 0);
});

test('overdueInvoices detects single overdue invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, invoice.number);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[0].dueDate, '2025-01-29');
});

test('overdueInvoices filters out draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);

  const r = overdueInvoices([draftResult.value], '2025-02-15');
  assert.equal(r.length, 0);
});

test('overdueInvoices filters out paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');

  const r = overdueInvoices([paymentResult.value], '2025-02-15');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes issued invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  assert.equal(invoice.status, 'issued');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'partially_paid');

  const r = overdueInvoices([paymentResult.value], '2025-02-15');
  assert.equal(r.length, 1);
});

test('overdueInvoices excludes invoices with future due dates', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET30');
  // dueDate will be 2025-02-14

  const r = overdueInvoices([invoice], '2025-02-13');
