test('lateFee calculates fee for 1 day overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29, due amount 1127

  const fee = lateFee(invoice, '2025-01-30');
  assert(fee > 0);
  // Fee = 1127 * 0.0004 * 1 = 0.4508, rounds to 45 cents
  assert.equal(fee, 45);
});

test('lateFee calculates fee for 10 days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-02-08');
  assert(fee > 0);
  // Fee = 1127 * 0.0004 * 10 = 4.508, rounds to 451 cents (4.51 EUR)
  assert.equal(fee, 451);
});

test('lateFee calculates fee for 30 days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-02-28');
  assert(fee > 0);
  // Fee = 1127 * 0.0004 * 30 = 13.524, rounds to 1352 cents
  assert.equal(fee, 1352);
});

